import { ImageResponse } from 'next/og';

export const alt = 'Abdul Wahid — AI/ML Developer';
export const size = { width: 1200, height: 630 };
export const contentType = 'image/png';

// Social share card (WhatsApp / LinkedIn / X previews), generated by
// Next.js at /opengraph-image. Brand: near-black, white, orange accent.
export default async function Image() {
  let anton: ArrayBuffer | undefined;
  try {
    const css = await (
      await fetch('https://fonts.googleapis.com/css2?family=Anton&display=swap', {
        headers: { 'User-Agent': 'Mozilla/5.0' },
      })
    ).text();
    const url = css.match(/url\((https:[^)]+?\.ttf)\)/)?.[1];
    if (url) anton = await (await fetch(url)).arrayBuffer();
  } catch {
    anton = undefined;
  }

  return new ImageResponse(
    (
      <div
        style={{
          width: '100%',
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
          backgroundColor: '#0a0a0a',
          padding: '72px',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '18px' }}>
          <div style={{ width: '26px', height: '26px', backgroundColor: '#f97316' }} />
          <div
            style={{
              color: '#e5e5e5',
              fontSize: '26px',
              letterSpacing: '6px',
            }}
          >
            ABDULWAHID.ME
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <div
            style={{
              color: '#ffffff',
              fontSize: '128px',
              lineHeight: 1,
              textTransform: 'uppercase',
              fontFamily: anton ? 'Anton' : 'sans-serif',
              fontWeight: anton ? 400 : 900,
              letterSpacing: anton ? '0px' : '-2px',
            }}
          >
            Abdul Wahid
          </div>
          <div
            style={{
              color: '#f97316',
              fontSize: '42px',
              letterSpacing: '10px',
              marginTop: '26px',
            }}
          >
            AI/ML DEVELOPER
          </div>
        </div>

        <div style={{ color: '#a3a3a3', fontSize: '30px' }}>
          Make the model. Question the result.
        </div>
      </div>
    ),
    {
      ...size,
      fonts: anton
        ? [{ name: 'Anton', data: anton, style: 'normal' as const, weight: 400 as const }]
        : [],
    }
  );
}
